    function run(uint _val, address _log) public payable {
        require(_val != 0);
        c.SetMinSum(_val); if (__ESBMC_reverted()) return;
        bool reverted; c.SetLogFile(_log); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted);
